def transform(grid):
    counts = {}
    for r in grid:
        for cell in r:
            counts[cell] = counts.get(cell, 0) + 1
    background = max(counts, key=counts.get)

    rows = len(grid)
    cols = len(grid[0])
    best = {'color': None, 'top': 0, 'left': 0, 'height': 0, 'width': 0}
    max_area = 0

    for color in range(10):
        if color == background:
            continue
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] != color:
                    continue
                for h in range(1, rows - i + 1):
                    for w in range(1, cols - j + 1):
                        valid = True
                        for di in range(h):
                            for dj in range(w):
                                if grid[i + di][j + dj] != color:
                                    valid = False
                                    break
                            if not valid:
                                break
                        if valid:
                            area = h * w
                            if area > max_area:
                                max_area = area
                                best = {
                                    'color': color,
                                    'top': i,
                                    'left': j,
                                    'height': h,
                                    'width': w
                                }

    output = [[background for _ in range(cols)] for _ in range(rows)]
    if best['height'] > 0 and best['width'] > 0:
        for di in range(best['height']):
            for dj in range(best['width']):
                output[best['top'] + di][best['left'] + dj] = best['color']
    return output
